update public.gifts g set
  slug = v.new_slug, name = v.name, description = v.description, notes = v.notes,
  price_aed = v.price::numeric, sale_price_aed = null, price_min_aed = v.price_min::numeric, price_max_aed = v.price_max::numeric,
  price_unit = null, price_basis = 'online', price_label = v.price_label,
  image_url = v.image_url, image_kind = 'uploaded', image_caption = 'Product photo from Peekaboo Uganda', photo_refs = null,
  status = 'available', status_changed_at = now()
from v where g.slug = v.old_slug;
select set_config('registry.allow_status_change', 'off', true);

