insert into public.gift_retailers (gift_id, retailer_id, product_url, url_verified, product_note, is_primary)
select g.id, r.id, v.url, true, v.note, true
from v join public.gifts g on g.slug = v.slug join public.retailers r on r.slug = 'peekaboo-ug'
on conflict (gift_id, retailer_id) do update set product_url = excluded.product_url, url_verified = true,
  product_note = excluded.product_note, is_primary = true;
delete from public.retailers where slug in ('mom-store', 'carters', 'mamas-and-papas', 'mumzworld', 'carrefour-uae', 'centrepoint');

-- Category notes described the Dubai shops; replace them.
update public.categories c set description = v.d from (values
  ('travel', 'Two routes: the Pibi 4-in-1 is car seat and stroller in one, or pick a car seat and a separate stroller.'),
  ('sleep-and-nursery', null::text),
  ('clothing', null::text),
  ('extras-and-inspiration', 'Extras from the original inspiration pictures, matched to Peekaboo products.')
) as v(slug, d) where c.slug = v.slug;

-- UGX only: no exchange rate, no AED document totals.
update public.registry_settings set
  aed_to_ugx_rate = null, rate_updated_at = null, rate_source = null,
  doc_budget_total_aed = null, doc_full_total_aed = null, doc_totals_note = null,
  prices_recorded_on = '2026-11-18',
  price_notice = 'Prices are from Peekaboo Uganda''s website on 18 November 2026 and may have changed. Please check on peekaboo.ug before buying.'
where id = 1;
